"use strict";(globalThis.webpackChunkidempiere_id_github_io=globalThis.webpackChunkidempiere_id_github_io||[]).push([[13809],{31879(e){e.exports=JSON.parse('{"tag":{"label":"functional","permalink":"/docs/tags/functional","allTagsPath":"/docs/tags","count":144,"items":[{"id":"new-features/v2.1/account-kind","title":"Account Kind","description":"Account Kind: a New Feature in iDempiere 2.1.","permalink":"/docs/new-features/v2.1/account-kind"},{"id":"new-features/v13/accounting-schema-valid-range","title":"Accounting Schema Valid Range","description":"The goal of this enhancement is to enable accounting schema to validate within a provided range of time, so that the documents having accounting dates out of the configured range do not post.","permalink":"/docs/new-features/v13/accounting-schema-valid-range"},{"id":"new-features/v1.0/accounting-viewer-improvements","title":"Accounting Viewer Improvements","description":"Review accounting entries without interrupting your workflow. The Accounting Viewer now opens as a standalone window instead of a blocking popup.","permalink":"/docs/new-features/v1.0/accounting-viewer-improvements"},{"id":"new-features/v9/add-access-tab-document-status-activity","title":"Add Access Tab Document Status Activity","description":"Currently Document status can be assigned single role or user but there is no way to configure multiple role or user assignment to document status.","permalink":"/docs/new-features/v9/add-access-tab-document-status-activity"},{"id":"new-features/v10/add-always-updatable-logic-override-flag","title":"Add Always Updatable Logic Override Flag","description":"When defining a column you can define if a value is updatable or always updatable (when you want to update it even if the record is marked as processed).","permalink":"/docs/new-features/v10/add-always-updatable-logic-override-flag"},{"id":"new-features/v10/add-customer-account-freightcostrule","title":"Add Customer Account FreightCostRule","description":"Add FREIGHTCOSTRULE_CustomerAccount where freight cost should be charged to the receiver/customer shipper account.","permalink":"/docs/new-features/v10/add-customer-account-freightcostrule"},{"id":"new-features/v10/add-fixed-price-discount-support-to-discount-schema","title":"Add Fixed Price Discount Support to Discount Schema","description":"Enhance discount schema to support the setting of fixed unit price for each discount break point.","permalink":"/docs/new-features/v10/add-fixed-price-discount-support-to-discount-schema"},{"id":"new-features/v8.2/add-gridform-toggle-button-to-detail-pane","title":"Add Grid/Form Toggle Button to Detail Pane","description":"The goal of the ticket is to allow users to switch between grid and form view at detail pane.","permalink":"/docs/new-features/v8.2/add-gridform-toggle-button-to-detail-pane"},{"id":"new-features/v11/add-java-options-field-to-setup","title":"Add Java Options Field To Setup","description":"Added a new field to the iDempiere server setup dialog, Java Options.","permalink":"/docs/new-features/v11/add-java-options-field-to-setup"},{"id":"new-features/v10/add-user-session-process-instance","title":"Add User Session Process Instance","description":"Add session reference on process instance to analyze/audit process and users action sequence from process audit.","permalink":"/docs/new-features/v10/add-user-session-process-instance"},{"id":"new-features/v10/after-migrate-helper","title":"After Migrate Helper","description":"This process helps to find potential problems after migration scripts are applied.","permalink":"/docs/new-features/v10/after-migrate-helper"},{"id":"new-features/v12/all-quantities-in-storage-per-product","title":"All Quantities in Storage Per Product","description":"When you want to know how many items of a product you have on hand, you can use the Storage Per Product report.","permalink":"/docs/new-features/v12/all-quantities-in-storage-per-product"},{"id":"new-features/v1.0/allocate-payment-to-charge","title":"Allocate Payment To Charge","description":"Allocate Payment To Charge: a New Feature in iDempiere 1.0.","permalink":"/docs/new-features/v1.0/allocate-payment-to-charge"},{"id":"new-features/v11/allow-to-specify-print-format-for-dashboard-content-report","title":"Allow to Specify Print Format for Dashboard Content Report","description":"Allow to Specify Print Format for Dashboard Content Report: a New Feature in iDempiere 11.","permalink":"/docs/new-features/v11/allow-to-specify-print-format-for-dashboard-content-report"},{"id":"new-features/v8.2/allowing-all-reference-type-on-attribute","title":"Allowing all reference type on attribute","description":"Attribute set has been powerful mechanism for attaching meta data to product or product instance since compiere days.","permalink":"/docs/new-features/v8.2/allowing-all-reference-type-on-attribute"},{"id":"new-features/v10/ask-for-secret-input-within-process","title":"Ask For Secret Input Within Process","description":"In iDempiere 2.1, the functionality to ask the user for input within a process was added.","permalink":"/docs/new-features/v10/ask-for-secret-input-within-process"},{"id":"new-features/v13/attachment-list","title":"Attachment List","description":"The list of attachment files has been usually stored in a ZIP file in the database (the default), or as an XML file for FileSystem and DB_LOB (Database with Large Object Support).","permalink":"/docs/new-features/v13/attachment-list"},{"id":"new-features/v10/bankcash-transfer-document","title":"Bank/Cash Transfer Document","description":"Add CBankTransfer table and MBankTransfer DocAction model class.","permalink":"/docs/new-features/v10/bankcash-transfer-document"},{"id":"new-features/v10/base-price-list","title":"Base Price List","description":"Now a base price list can be defined for any price list.","permalink":"/docs/new-features/v10/base-price-list"},{"id":"new-features/v9/cloud-upload-interface-for-report-viewer-and-scheduler","title":"Cloud Upload Interface for Report Viewer and Scheduler","description":"Add cloud upload interface for report viewer and scheduler.","permalink":"/docs/new-features/v9/cloud-upload-interface-for-report-viewer-and-scheduler"},{"id":"new-features/v2.0/combinations-without-org","title":"Combinations Without Org","description":"Combinations Without Org: a New Feature in iDempiere 2.0.","permalink":"/docs/new-features/v2.0/combinations-without-org"},{"id":"new-features/v1.0/configurable-copy-fields","title":"Configurable Copy Fields","description":"Configurable Copy Fields: a New Feature in iDempiere 1.0.","permalink":"/docs/new-features/v1.0/configurable-copy-fields"},{"id":"new-features/v13/configurable-keikai-editable","title":"Configurable Keikai editable","description":"Make the Keikai spreadsheet viewer read-only state configurable per context via SysConfig keys","permalink":"/docs/new-features/v13/configurable-keikai-editable"},{"id":"new-features/v1.0/confirmdocvoidclose","title":"Confirm Document Void / Close","description":"Closing and Voiding documents can be a dangerous not-reversible operation.","permalink":"/docs/new-features/v1.0/confirmdocvoidclose"},{"id":"new-features/v10/consider-prepared-shipments-as-no-longer-available","title":"Consider prepared shipments as no longer available","description":"Consider prepared shipments as no longer available: a New Feature in iDempiere 10.","permalink":"/docs/new-features/v10/consider-prepared-shipments-as-no-longer-available"},{"id":"new-features/v1.0/copy-from-bank-statement","title":"Copy From Bank Statement","description":"This new feature adds CopyFrom on Bank Statement.","permalink":"/docs/new-features/v1.0/copy-from-bank-statement"},{"id":"new-features/v6.2/copy-or-move-tenant","title":"Copy or Move Tenant","description":"This feature was introduced in version 6.2 and it has received improvements and bug fixes in different versions.","permalink":"/docs/new-features/v6.2/copy-or-move-tenant"},{"id":"new-features/v2.1/country-group","title":"Country Group","description":"Country Group: a New Feature in iDempiere 2.1.","permalink":"/docs/new-features/v2.1/country-group"},{"id":"new-features/v8.2/create-window-tab-field-from-table","title":"Create Window, Tab & Field from Table","description":"The goal of the ticket is to allow system users to create the Window, Tab & Field records automatically from the Table and Column window.","permalink":"/docs/new-features/v8.2/create-window-tab-field-from-table"},{"id":"new-features/v2.0/crm","title":"CRM Sales Management","description":"Sales Leads Management with configurable charts and dashboards","permalink":"/docs/new-features/v2.0/crm"},{"id":"new-features/v9/customstariffnumber-in-products-and-enhanced-import","title":"CustomsTariffNumber in Products and enhanced import","description":"CustomsTariffNumber in Products and enhanced import: a New Feature in iDempiere 9.","permalink":"/docs/new-features/v9/customstariffnumber-in-products-and-enhanced-import"},{"id":"new-features/v2.0/dashboard-chart","title":"Dashboard Chart","description":"Dashboard Chart: a New Feature in iDempiere 2.0.","permalink":"/docs/new-features/v2.0/dashboard-chart"},{"id":"new-features/v8.2/dashboard-report-use-sql-and-range-parameters","title":"Dashboard Report Use Sql And Range Parameters","description":"It is now possible to use @SQL= notation and set range parameters for embedded report on the home page.","permalink":"/docs/new-features/v8.2/dashboard-report-use-sql-and-range-parameters"},{"id":"new-features/v10/deductible-and-non-deductible-input-tax","title":"Deductible and Non Deductible Input Tax","description":"Deductible and Non Deductible Input Tax: a New Feature in iDempiere 10.","permalink":"/docs/new-features/v10/deductible-and-non-deductible-input-tax"},{"id":"new-features/v10/delete-record-with-confirmation-logic","title":"Delete Record with Confirmation Logic","description":"Delete Record with Confirmation Logic: a New Feature in iDempiere 10.","permalink":"/docs/new-features/v10/delete-record-with-confirmation-logic"},{"id":"new-features/v6.2/disallow-re-running-a-process-that-is-already-being-executed","title":"Disallow re-running a process that is already being executed","description":"Sometimes when a user runs a heavy report/process more than once, the perfomance cost is really expensive.","permalink":"/docs/new-features/v6.2/disallow-re-running-a-process-that-is-already-being-executed"},{"id":"new-features/v7.1/display-logic-for-print-format-item-in-pdf","title":"Display Logic for Print Format Item in PDF","description":"Now is possible to set a Display Logic for a Print Format Item rendered as PDF format.","permalink":"/docs/new-features/v7.1/display-logic-for-print-format-item-in-pdf"},{"id":"new-features/v10/document-type-for-production-and-bank-statement","title":"Document Type for Production and Bank Statement","description":"Document Type for Production and Bank Statement: a New Feature in iDempiere 10.","permalink":"/docs/new-features/v10/document-type-for-production-and-bank-statement"},{"id":"new-features/v8.2/drop-rename-db-objects","title":"Drop Rename DB Objects","description":"Five new processes have been added to allow some operations directly in the database without the need to open a DB manager (like DBeaver or pgadmin).","permalink":"/docs/new-features/v8.2/drop-rename-db-objects"},{"id":"new-features/v1.0/dynamic-zoom","title":"Dynamic Zoom","description":"This enhancement allow the application to determine zoom window at runtime through the use of data driven SQL rule.","permalink":"/docs/new-features/v1.0/dynamic-zoom"},{"id":"new-features/v2.1/ease-initial-client-setup","title":"Ease Initial Client Setup","description":"In order to ease the initial setup of a new tenant three options were added to the \'Initial Client Setup Process\':","permalink":"/docs/new-features/v2.1/ease-initial-client-setup"},{"id":"new-features/v2.1/email-improvements","title":"EMail Improvements","description":"The following columns were added to the table AD_UserMail in order to improve the monitoring of emails:","permalink":"/docs/new-features/v2.1/email-improvements"},{"id":"new-features/v11/enable-showing-inactive-records-through-reference","title":"Enable Showing Inactive Records through Reference","description":"Enable Showing Inactive Records through Reference: a New Feature in iDempiere 11.","permalink":"/docs/new-features/v11/enable-showing-inactive-records-through-reference"},{"id":"new-features/v8.2/enhanced-vendor-specific-price-list-generation","title":"Enhanced vendor specific price list generation","description":"To better support the generation of vendor specific price lists it was necessary, to allow prices to be included where the vendor is not the current vendor.","permalink":"/docs/new-features/v8.2/enhanced-vendor-specific-price-list-generation"},{"id":"new-features/v2.0/estimated-landed-cost","title":"Estimated Landed Cost","description":"Support estimated landed cost for Average Costing.","permalink":"/docs/new-features/v2.0/estimated-landed-cost"},{"id":"new-features/v9/excel-file-preview-at-report-and-attachment-viewer","title":"Excel File Preview at Report and Attachment Viewer","description":"Add Excel file (xls, xlsx and csv) preview support to report and attachment viewer.","permalink":"/docs/new-features/v9/excel-file-preview-at-report-and-attachment-viewer"},{"id":"new-features/v12/exclude-freight-charges-from-payment-discount","title":"Exclude Freight Charges from Payment Discount","description":"To improve the accuracy of payment discounts, a new flag IsExcludedFromDiscount was introduced on the Charge (C_Charge) table.","permalink":"/docs/new-features/v12/exclude-freight-charges-from-payment-discount"},{"id":"new-features/v3.0/exclude-locators-for-demand-operations","title":"Exclude Locators for Demand Operations","description":"Exclude Locators for Demand Operations: a New Feature in iDempiere 3.0.","permalink":"/docs/new-features/v3.0/exclude-locators-for-demand-operations"},{"id":"new-features/v11/export-sql-insert-scripts","title":"Export SQL Insert Scripts","description":"Export SQL Insert Scripts: a New Feature in iDempiere 11.","permalink":"/docs/new-features/v11/export-sql-insert-scripts"},{"id":"new-features/v12/feature-fast-entity-type-identification","title":"FEATURE: Fast entity type identification","description":"Entity type identification can be activated in the User preference window by checking the \'Show Technical Information on Help\' flag","permalink":"/docs/new-features/v12/feature-fast-entity-type-identification"},{"id":"new-features/v13/uom-qtyentered-physical-inventory","title":"Feature: Support UOM and QtyEntered on Physical Inventory and Inventory Increase/Decrease","description":"Adds UOM and QtyEntered fields to Physical Inventory and Inventory Increase/Decrease windows.","permalink":"/docs/new-features/v13/uom-qtyentered-physical-inventory"},{"id":"new-features/v8.2/financial-report-exclude-all-adjustment-periods","title":"Financial Report : Exclude all adjustment periods","description":"Until v8.2, financial reports were excluding the last adjustement period if it ends on the same day as the period selected for the report.","permalink":"/docs/new-features/v8.2/financial-report-exclude-all-adjustment-periods"},{"id":"new-features/v1.0/financialreport-enhancement","title":"Financial Report Enhancement","description":"Financial Report Enhancement: a New Feature in iDempiere 1.0.","permalink":"/docs/new-features/v1.0/financialreport-enhancement"},{"id":"new-features/v1.0/find-window","title":"Find Window","description":"The history button was moved from toolbar to search window.","permalink":"/docs/new-features/v1.0/find-window"},{"id":"new-features/v8.2/find-window-extended-controls","title":"Find Window Extended Controls","description":"Find Window Extended Controls: a New Feature in iDempiere 8.2.","permalink":"/docs/new-features/v8.2/find-window-extended-controls"},{"id":"new-features/v1.0/fixed-assets","title":"Fixed Assets Stabilization","description":"With the release 1.0 of iDempiere the Fixed Assets extension was fully integrated and a stabilization effort was contributed.","permalink":"/docs/new-features/v1.0/fixed-assets"},{"id":"new-features/v10/flat-view-menu-tree-enhancements","title":"Flat View Menu Tree Enhancements","description":"Add ZK_FLAT_VIEW_MENU_TREE system config, tenant level and default to N.","permalink":"/docs/new-features/v10/flat-view-menu-tree-enhancements"},{"id":"new-features/v1.0/gljournalgenerator","title":"GL Journal Generator","description":"GL Journal Generator allows you to configure the generation of GL Journals based on previous journals movements.","permalink":"/docs/new-features/v1.0/gljournalgenerator"},{"id":"new-features/v1.0/gl-reconciliation","title":"GL Reconciliation","description":"GL Reconciliation: a New Feature in iDempiere 1.0.","permalink":"/docs/new-features/v1.0/gl-reconciliation"},{"id":"new-features/v8.2/how-to-configure-the-toolbar","title":"How To Configure The Toolbar","description":"How To Configure The Toolbar: a New Feature in iDempiere 8.2.","permalink":"/docs/new-features/v8.2/how-to-configure-the-toolbar"},{"id":"new-features/v9/how-to-using-print-format-item-scripts-in-reports","title":"How To: Using Print Format Item Scripts In Reports","description":"How To: Using Print Format Item Scripts In Reports: a New Feature in iDempiere 9.","permalink":"/docs/new-features/v9/how-to-using-print-format-item-scripts-in-reports"},{"id":"release-changelogs/v10","title":"iDempiere 10 changelog","description":"Bug fixes and non-disruptive features integrated into the iDempiere 10 stable release, listed by date from newest to oldest.","permalink":"/docs/release-changelogs/v10"},{"id":"release-changelogs/v11","title":"iDempiere 11 changelog","description":"Bug fixes and non-disruptive features integrated into the iDempiere 11 stable release, listed by date from newest to oldest.","permalink":"/docs/release-changelogs/v11"},{"id":"release-changelogs/v12","title":"iDempiere 12 changelog","description":"Bug fixes and non-disruptive features integrated into the iDempiere 12 stable release, listed by date from newest to oldest.","permalink":"/docs/release-changelogs/v12"},{"id":"release-changelogs/v13","title":"iDempiere 13 changelog","description":"Bug fixes and non-disruptive features integrated into the iDempiere 13 stable release, listed by date from newest to oldest.","permalink":"/docs/release-changelogs/v13"},{"id":"new-features/v1.0/idempiere-workshop-2014","title":"iDempiere workshop August 2014","description":"There was a iDempiere workshop in August 2014 held by Carlos Ruiz (organized by Thomas Bayen)","permalink":"/docs/new-features/v1.0/idempiere-workshop-2014"},{"id":"new-features/v2.1/implement-document-action-for-production-document","title":"Implement Document Action for Production Document","description":"Now the Production document behaves fully as an iDempiere document, with the corresponding options to Prepare, Complete, Close, Void, Reverse Correct a","permalink":"/docs/new-features/v2.1/implement-document-action-for-production-document"},{"id":"new-features/v7.1/implement-notation-sql-for-display-logic","title":"Implement notation @SQL for display logic","description":"It is possible to base a display logic on a sql query, according to its result.","permalink":"/docs/new-features/v7.1/implement-notation-sql-for-display-logic"},{"id":"new-features/v2.1/improve-accounting-adjustment-periods","title":"Improve Accounting Adjustment Periods","description":"The purpose of this enhancement is to give accounting users the ability to create GL Journal entries against an \\"Adjustment Period\\".","permalink":"/docs/new-features/v2.1/improve-accounting-adjustment-periods"},{"id":"new-features/v2.0/improve-asi-fifo","title":"Improve ASI FIFO","description":"Previously the Attribute Set Instance (ASI) was being used to control FIFO/LIFO warehouse picking methods.","permalink":"/docs/new-features/v2.0/improve-asi-fifo"},{"id":"new-features/v1.0/document-sequence-improved","title":"Improved Document Sequence","description":"Improved Document Sequence: a New Feature in iDempiere 1.0.","permalink":"/docs/new-features/v1.0/document-sequence-improved"},{"id":"new-features/v1.0/infoproduct","title":"Improved Info Product","description":"Improved Info Product: a New Feature in iDempiere 1.0.","permalink":"/docs/new-features/v1.0/infoproduct"},{"id":"new-features/v1.0/info-window","title":"Info Window","description":"Info Window: a New Feature in iDempiere 1.0.","permalink":"/docs/new-features/v1.0/info-window"},{"id":"new-features/v10/info-window-generate-invoice-manual","title":"Info Window Generate Invoice (manual)","description":"Generate invoice (manual) migrated to info window","permalink":"/docs/new-features/v10/info-window-generate-invoice-manual"},{"id":"new-features/v10/info-window-generate-shipment-manual","title":"Info Window Generate Shipment (manual)","description":"Generate shipments (manual) migrated to info window","permalink":"/docs/new-features/v10/info-window-generate-shipment-manual"},{"id":"new-features/v1.0/cost-adjustment","title":"Inventory Cost Adjustment","description":"A new window to allow the entering of cost adjustment for product.","permalink":"/docs/new-features/v1.0/cost-adjustment"},{"id":"new-features/v1.0/inventory-documents","title":"Inventory Documents","description":"Inventory Documents: a New Feature in iDempiere 1.0.","permalink":"/docs/new-features/v1.0/inventory-documents"},{"id":"new-features/v2.1/invoice-not-realized-gainloss-fixes","title":"Invoice Not Realized Gain/Loss Fixes","description":"Invoice Not Realized Gain/Loss Fixes: a New Feature in iDempiere 2.1.","permalink":"/docs/new-features/v2.1/invoice-not-realized-gainloss-fixes"},{"id":"new-features/v9/jasper-report-deployment-refactoring-and-improvement","title":"Jasper Report Deployment Refactoring and Improvement","description":"Refactor and improve the deployment of Jasper Report.","permalink":"/docs/new-features/v9/jasper-report-deployment-refactoring-and-improvement"},{"id":"new-features/v11/json-field-type","title":"JSON Field Type","description":"JSON is a commonly used data format with diverse applications in data interchange, including web applications communicating with servers.","permalink":"/docs/new-features/v11/json-field-type"},{"id":"new-features/v10/label-feature","title":"Label Feature","description":"This feature should allow users to assign metadata (labels) to any iDempiere record.","permalink":"/docs/new-features/v10/label-feature"},{"id":"new-features/v2.1/manually-selecting-attribute-set-instance","title":"Manually Selecting Attribute Set Instance","description":"We find it a bit hard to work with serially managed products in iDempiere as we need to create 1 line per serial number.","permalink":"/docs/new-features/v2.1/manually-selecting-attribute-set-instance"},{"id":"new-features/v1.0/manufacturing-light","title":"Manufacturing Light","description":"Manufacturing Light: a New Feature in iDempiere 1.0.","permalink":"/docs/new-features/v1.0/manufacturing-light"},{"id":"new-features/v1.0/map-route-on-locations","title":"Map Route On Locations","description":"Map Route On Locations: a New Feature in iDempiere 1.0.","permalink":"/docs/new-features/v1.0/map-route-on-locations"},{"id":"new-features/v9/messages-at-client-level","title":"Messages at Client Level","description":"Messages are defined and translated at System level.","permalink":"/docs/new-features/v9/messages-at-client-level"},{"id":"new-features/v6.2/migrate-an-id-or-uuid","title":"Migrate an ID or UUID","description":"This functionality allows to change the ID or UUID of a record.","permalink":"/docs/new-features/v6.2/migrate-an-id-or-uuid"},{"id":"new-features/v7.1/migrate-storage-provider","title":"Migrate Storage Provider","description":"This functionality migrates files between storage providers","permalink":"/docs/new-features/v7.1/migrate-storage-provider"},{"id":"new-features/v2.1/min-amount-for-create-invoices","title":"Min Amount For Create Invoices","description":"The Generate Invoices process can now be restricted to generate just invoices which total is greater or equal than a specified minimum amount.","permalink":"/docs/new-features/v2.1/min-amount-for-create-invoices"},{"id":"new-features/v11/min-max-validation-process-parameters","title":"Min Max Validation Process Parameters","description":"Min Max Validation Process Parameters: a New Feature in iDempiere 11.","permalink":"/docs/new-features/v11/min-max-validation-process-parameters"},{"id":"new-features/v1.0/mixedpospayments","title":"Mixed POS Payments on Sales Order","description":"Sales Order window was modified to allow management of Mixed Payments on POS Orders, this is, a sales order that is paid with different tender types.","permalink":"/docs/new-features/v1.0/mixedpospayments"},{"id":"new-features/v10/multi-warehouse-inventory-valuation-report","title":"Multi Warehouse Inventory Valuation Report","description":"Multi Warehouse Inventory Valuation Report: a New Feature in iDempiere 10.","permalink":"/docs/new-features/v10/multi-warehouse-inventory-valuation-report"},{"id":"new-features/v12/multiple-payments-against-statement-line-by-payment-batch","title":"Multiple Payments against statement line by Payment Batch","description":"Tag Payment Into Batch to Bank Statement Line and Document Workflow Support for Payment Into Batch","permalink":"/docs/new-features/v12/multiple-payments-against-statement-line-by-payment-batch"},{"id":"new-features/v9/multiple-smtp-per-tenant","title":"Multiple SMTP Per Tenant","description":"Since v9, is possible to define several SMTP servers per tenant.","permalink":"/docs/new-features/v9/multiple-smtp-per-tenant"},{"id":"new-features/v10/negate-option-for-chosen-multiple-component-parameter","title":"Negate Option for Chosen Multiple Component parameter","description":"Negate Option for Chosen Multiple Component parameter: a New Feature in iDempiere 10.","permalink":"/docs/new-features/v10/negate-option-for-chosen-multiple-component-parameter"},{"id":"new-features/v13/new-accounting-dimensions","title":"New Accounting Dimensions","description":"in iDempiere, Activity use for cost center as well as department.","permalink":"/docs/new-features/v13/new-accounting-dimensions"},{"id":"new-features/v12/new-fields-in-country","title":"New Fields in Country","description":"New Fields in Country: a New Feature in iDempiere 12.","permalink":"/docs/new-features/v12/new-fields-in-country"},{"id":"new-features/v6.2/on-start-schedule","title":"On Start Schedule","description":"On Start Schedule: a New Feature in iDempiere 6.2.","permalink":"/docs/new-features/v6.2/on-start-schedule"},{"id":"new-features/v9/osgi-interface-to-create-custom-header-and-footer","title":"OSGi Interface to Create Custom Header and Footer","description":"Add AD_PrintHeaderFooter table and OSGi interface IPrintHeaderFooter to replace Standard Header and Footer for tabular (non-form) report.","permalink":"/docs/new-features/v9/osgi-interface-to-create-custom-header-and-footer"},{"id":"new-features/v13/override-workflow-responsible","title":"Override Workflow Responsible","description":"Workflow are normally defined at system tenant.","permalink":"/docs/new-features/v13/override-workflow-responsible"},{"id":"new-features/v1.0/payment-batch","title":"Payment Batch","description":"Main goal of this feature is to allow users to group payments in batches in order to reconcile several payments in one single statement line.","permalink":"/docs/new-features/v1.0/payment-batch"},{"id":"new-features/v2.1/payment-selection-improvements","title":"Payment Selection Improvements","description":"The \'Payment Selection\' process and the corresponding \'Payment Selection (manual)\' has been improved:","permalink":"/docs/new-features/v2.1/payment-selection-improvements"},{"id":"new-features/v11/period-close-disallow-when-unposted-documents-exists","title":"Period Close Disallow When Unposted Documents Exists","description":"The purpose of this change better controlling between period close and un-posted documents.","permalink":"/docs/new-features/v11/period-close-disallow-when-unposted-documents-exists"},{"id":"new-features/v11/period-control-document-close","title":"Period Control Document Close","description":"The purpose of this change is to close a period for new documents first, so it is not allowed to enter new documents, but reposting documents remains possible.","permalink":"/docs/new-features/v11/period-control-document-close"},{"id":"new-features/v12/prepay-order-configurable-shipment-and-invoicing","title":"Prepay Order Configurable Shipment and Invoicing","description":"Prepay Order Configurable Shipment and Invoicing: a New Feature in iDempiere 12.","permalink":"/docs/new-features/v12/prepay-order-configurable-shipment-and-invoicing"},{"id":"new-features/v9/print-format-editor","title":"Print Format Editor","description":"Print Format Editor: a New Feature in iDempiere 9.","permalink":"/docs/new-features/v9/print-format-editor"},{"id":"new-features/v8.2/print-format-item-script","title":"Print Format Item Script","description":"Now you can do numeric calculations over the columns of a print format, and even execute SQL to obtain values to print.","permalink":"/docs/new-features/v8.2/print-format-item-script"},{"id":"new-features/v11/private-access-window","title":"Private Access Window","description":"Roles with \\"Personal Lock\\" permission are able to set locks in records.","permalink":"/docs/new-features/v11/private-access-window"},{"id":"new-features/v12/reactivation-of-invoices","title":"Reactivation of Invoices","description":"Reactivation is configurable per Role and Document Type.","permalink":"/docs/new-features/v12/reactivation-of-invoices"},{"id":"new-features/v13/read-access-to-tables-not-in-role-table-access-list","title":"Read Access To Tables Not In Role Table Access List","description":"Read Access To Tables Not In Role Table Access List: a New Feature in iDempiere 13.","permalink":"/docs/new-features/v13/read-access-to-tables-not-in-role-table-access-list"},{"id":"new-features/v10/record-id-editor","title":"Record ID Editor","description":"The Record ID field type allows two actions - select Table and Record, and zoom to the selected record.","permalink":"/docs/new-features/v10/record-id-editor"},{"id":"new-features/v2.1/recurring-run-automation","title":"Recurring Run Automation","description":"The Recurring functionality can now be used for subscriptions where you want to generate recurring documents automatically.","permalink":"/docs/new-features/v2.1/recurring-run-automation"},{"id":"new-features/v9/replace-create-from-form-with-info-window-form","title":"Replace Create From Form With Info Window Form","description":"Use Info Window and Process to replace existing Create From custom form.","permalink":"/docs/new-features/v9/replace-create-from-form-with-info-window-form"},{"id":"new-features/v1.0/request-calendar-dashboard","title":"Request Calendar Dashboard","description":"The \\"Request Calendar\\" allows the user to create, view and query quickly any request.","permalink":"/docs/new-features/v1.0/request-calendar-dashboard"},{"id":"new-features/v9/reset-accounting-documents-also-without-postings","title":"Reset Accounting Documents also without Postings","description":"Reset Accounting Documents also without Postings: a New Feature in iDempiere 9.","permalink":"/docs/new-features/v9/reset-accounting-documents-also-without-postings"},{"id":"new-features/v6.2/revenue-recognition","title":"Revenue Recognition","description":"Revenue Recognition is working now for both Time and Event based recognition requirements.","permalink":"/docs/new-features/v6.2/revenue-recognition"},{"id":"new-features/v1.0/reverseaccrual","title":"Reverse Accrual","description":"Implement reverse accrual for shipment, invoice, inventory and payment document.","permalink":"/docs/new-features/v1.0/reverseaccrual"},{"id":"new-features/v9/reverse-prepared-payment-process","title":"Reverse Prepared Payment Process","description":"This process was implemented to be able to fix a processed Payment Selection record without the need to hack DB.","permalink":"/docs/new-features/v9/reverse-prepared-payment-process"},{"id":"new-features/v8.2/reverse-sign-in-financial-report-cell","title":"Reverse Sign In Financial Report Cell","description":"Reverse Sign In Financial Report Cell: a New Feature in iDempiere 8.2.","permalink":"/docs/new-features/v8.2/reverse-sign-in-financial-report-cell"},{"id":"new-features/v8.2/set-default-contactuser-in-documents","title":"Set default Contact/User in Documents","description":"The goal of the ticket is to ease the document creation process by setting default BillTo/ShipTo users based on a new flag on the User/Contact window.","permalink":"/docs/new-features/v8.2/set-default-contactuser-in-documents"},{"id":"new-features/v9/shipment-on-availability-when-products-available","title":"Shipment On Availability When Products Available","description":"Shipment On Availability When Products Available: a New Feature in iDempiere 9.","permalink":"/docs/new-features/v9/shipment-on-availability-when-products-available"},{"id":"new-features/v8.2/show-products-not-on-price-list","title":"Show Products Not On Price List","description":"One of the most common problems when entering sales or purchase order lines is hitting the error:","permalink":"/docs/new-features/v8.2/show-products-not-on-price-list"},{"id":"new-features/v1.0/gljournal","title":"Simplified GL Journal","description":"Simplified GL Journal: a New Feature in iDempiere 1.0.","permalink":"/docs/new-features/v1.0/gljournal"},{"id":"new-features/v11/single-sign-on","title":"Single Sign-On","description":"iDempiere 11 has added support for single sign-On.","permalink":"/docs/new-features/v11/single-sign-on"},{"id":"new-features/v9/sql-workflow-condition","title":"SQL Workflow Condition","description":"SQL Workflow Condition: a New Feature in iDempiere 9.","permalink":"/docs/new-features/v9/sql-workflow-condition"},{"id":"new-features/v8.2/starting-other-workflows-within-a-workflow","title":"Starting other workflows within a workflow","description":"You can now start other workflows from within a workflow.","permalink":"/docs/new-features/v8.2/starting-other-workflows-within-a-workflow"},{"id":"new-features/v11/stocked-expense-type-product","title":"Stocked Expense Type Product","description":"Stocked Expense Type Product: a New Feature in iDempiere 11.","permalink":"/docs/new-features/v11/stocked-expense-type-product"},{"id":"new-features/v1.0/storage-improvements","title":"Storage Improvements","description":"Storage Improvements: a New Feature in iDempiere 1.0.","permalink":"/docs/new-features/v1.0/storage-improvements"},{"id":"new-features/v13/storage-validator-osgi-service","title":"Storage Validator OSGI Service","description":"This enhancement introduces a new Storage Validator extension point to iDempiere.","permalink":"/docs/new-features/v13/storage-validator-osgi-service"},{"id":"new-features/v11/support-quick-info-widget-for-info-windows","title":"Support Quick Info Widget for Info Windows","description":"The Quick Info widget can be defined in System, through the Status Line window.","permalink":"/docs/new-features/v11/support-quick-info-widget-for-info-windows"},{"id":"new-features/v12/support-uom-on-inventory-move","title":"Support UOM On Inventory Move","description":"This new feature introduces the UOM and Qty Entered fields in Inventory Move Line.","permalink":"/docs/new-features/v12/support-uom-on-inventory-move"},{"id":"new-features/v8.2/suspend-workflow-until-commit","title":"Suspend workflow until commit","description":"This feature allows to suspend a workflow upto the actual transaction is committed.","permalink":"/docs/new-features/v8.2/suspend-workflow-until-commit"},{"id":"new-features/v11/tax-rate-tab-in-tax-category","title":"Tax Rate Tab in Tax Category","description":"There\'s a new tab in the Tax Category window that allows users to work with tax rates directly from this window.","permalink":"/docs/new-features/v11/tax-rate-tab-in-tax-category"},{"id":"new-features/v9/tenant-administrator-roles","title":"Tenant Administrator Roles","description":"Tenant Administrator Roles: a New Feature in iDempiere 9.","permalink":"/docs/new-features/v9/tenant-administrator-roles"},{"id":"new-features/v10/tenant-time-zone-for-cron-scheduler","title":"Tenant Time Zone for Cron Scheduler","description":"Add option to support the scheduling of cron pattern scheduler with tenant time zone instead of server time zone.","permalink":"/docs/new-features/v10/tenant-time-zone-for-cron-scheduler"},{"id":"new-features/v11/timezone-by-organization","title":"Timezone By Organization","description":"In ticket IDEMPIERE-5093, the possibility of define a timezone in tenant was implemented.","permalink":"/docs/new-features/v11/timezone-by-organization"},{"id":"new-features/v2.1/tree-driven-by-search-key","title":"Tree Driven by Search Key","description":"Now you can define a tree to be driven by its Search key","permalink":"/docs/new-features/v2.1/tree-driven-by-search-key"},{"id":"new-features/v3.0/tree-on-any-table","title":"Tree On Any Table","description":"Now you can define a tree for any table that has Summary Level field (column name IsSummary).","permalink":"/docs/new-features/v3.0/tree-on-any-table"},{"id":"new-features/v11/un-cefact-code-in-uom","title":"UN CEFACT Code in UOM","description":"The UN/CEFACT Code was added to Unit of Measure window, this standard code is used in many integrations (like ZUGFeRD or Electronic Invoices).","permalink":"/docs/new-features/v11/un-cefact-code-in-uom"},{"id":"new-features/v12/unallocated-cash-and-payment-selection-configurable-business-partner","title":"Unallocated Cash and Payment Selection Configurable Business Partner","description":"Unallocated Cash and Payment Selection Configurable Business Partner: a New Feature in iDempiere 12.","permalink":"/docs/new-features/v12/unallocated-cash-and-payment-selection-configurable-business-partner"},{"id":"new-features/v2.0/validate-email-format","title":"Validate EMail Format","description":"In order to increase the data quality and avoid mistakes a basic validation is done now on EMail address to ensure it conforms to the syntax rules of RFC 822.","permalink":"/docs/new-features/v2.0/validate-email-format"},{"id":"new-features/v9/vendor-lead","title":"Vendor Lead","description":"Idea is to use Lead to manage both Sales and Purchases sides.","permalink":"/docs/new-features/v9/vendor-lead"},{"id":"new-features/v12/virtual-column-as-report-parameter","title":"Virtual Column as Report Parameter","description":"Virtual Column as Report Parameter: a New Feature in iDempiere 12.","permalink":"/docs/new-features/v12/virtual-column-as-report-parameter"},{"id":"new-features/v6.2/virtual-ui-column","title":"Virtual UI Column","description":"Virtual UI Column: a New Feature in iDempiere 6.2.","permalink":"/docs/new-features/v6.2/virtual-ui-column"},{"id":"new-features/v10/workflow-email-notification-enhancements","title":"Workflow EMail Notification Enhancements","description":"Make attachment of PDF document to Workflow EMail Notification optional.","permalink":"/docs/new-features/v10/workflow-email-notification-enhancements"}],"unlisted":false}}')}}]);